package set_command

// Entries is every value this command reads off a command line, one field per
// entry of its command.yaml: FullCommand, the whole command line, then one per
// entry of `args` and one per entry of `flags`, each tagged with the id the
// generic CommandHandler fills it by. InternalPureHandler is handed one,
// already filled.
// Generated by `agnos build` — do not edit by hand.
type Entries struct {
	FullCommand     []string `id:"FullCommand"`
	Command         string   `id:"Command"`
	Name            string   `id:"Name"`
	Help            string   `id:"Help"`
	Category        string   `id:"Category"`
	LongDescription string   `id:"LongDescription"`
	Identifier      []string `id:"Identifier"`
	Example         []string `id:"Example"`
	Hidden          bool     `id:"Hidden"`
	Visible         bool     `id:"Visible"`
	Priority        int      `id:"Priority"`
	Before          string   `id:"Before"`
	After           string   `id:"After"`
	Segments        int      `id:"Segments"`
	Strict          bool     `id:"Strict"`
	Loose           bool     `id:"Loose"`
	Clear           []string `id:"Clear"`
}
